import java.util.*;
import java.io.*;

public class ar {

    static class FastInput {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FastInput() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        String getNextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return tokenizer.nextToken();
        }

        int getNextInt() {
            return Integer.parseInt(getNextToken());
        }
    }

    public static void main(String[] args) throws Exception {
        FastInput fi = new FastInput();
        int totalNumbers = fi.getNextInt();
        int maxBudget = fi.getNextInt();
        int[] sequence = new int[totalNumbers];
        for (int i = 0; i < totalNumbers; i++) {
            sequence[i] = fi.getNextInt();
        }

        if ((totalNumbers & 1) == 1) {
            System.out.print(0);
            return;
        }

        Map<Integer, Integer> differenceMap = new HashMap<>();
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i < totalNumbers; i++) {
            if (sequence[i] % 2 == 0) evenCount++;
            else oddCount++;
            if (evenCount > 0 && oddCount > 0 && evenCount == oddCount && i + 1 < totalNumbers) {
                differenceMap.put(i, Math.abs(sequence[i] - sequence[i + 1]));
            }
        }

        if (differenceMap.isEmpty()) {
            System.out.print(0);
        } else if (differenceMap.size() == 1) {
            int val = new ArrayList<>(differenceMap.values()).get(0);
            System.out.print(val <= maxBudget ? 1 : 0);
        } else {
            List<Integer> diffValues = new ArrayList<>(differenceMap.values());
            Collections.sort(diffValues);
            int count = 0;
            for (int v : diffValues) {
                if (v <= maxBudget) {
                    maxBudget -= v;
                    count++;
                } else {
                    break;
                }
            }
            System.out.print(count);
        }
    }
}
