#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int totalNumbers, maxBudget;
    cin >> totalNumbers >> maxBudget;
    vector<int> sequence(totalNumbers);
    for (int i = 0; i < totalNumbers; i++) {
        cin >> sequence[i];
    }

    if ((totalNumbers & 1) == 1) {
        cout << 0;
        return 0;
    }

    unordered_map<int, int> differenceMap;
    int evenCount = 0, oddCount = 0;
    for (int i = 0; i < totalNumbers; i++) {
        if (sequence[i] % 2 == 0) evenCount++;
        else oddCount++;
        if (evenCount > 0 && oddCount > 0 && evenCount == oddCount && i + 1 < totalNumbers) {
            differenceMap[i] = abs(sequence[i] - sequence[i + 1]);
        }
    }

    if (differenceMap.empty()) {
        cout << 0;
    } else if (differenceMap.size() == 1) {
        int val = differenceMap.begin()->second;
        cout << (val <= maxBudget ? 1 : 0);
    } else {
        std::vector<int> diffValues;
        for (const auto& kv : differenceMap) {
            diffValues.push_back(kv.second);
        }
        std::sort(diffValues.begin(), diffValues.end());
        int count = 0;
        for (int v : diffValues) {
            if (v <= maxBudget) {
                maxBudget -= v;
                count++;
            } else {
                break;
            }
        }
        cout << count;
    }
    return 0;
}
